export const SUPPORTED_LOCALES = Object.freeze(['en', 'hi']);
const HINDI_CASE_INSENSITIVE = new Map(
  Object.entries(HINDI).map(([source, translated]) => [source.toLocaleLowerCase(), translated])
);

const DYNAMIC_TRANSLATIONS = [
  [/^(.+?) — from (.+) p\.a\.$/u, (match) => `${translateText(match[1], 'hi')} — ${match[2]} वार्षिक से शुरू`],
  [/^Reference (.+)$/u, (match) => `संदर्भ ${match[1]}`],
  [/^Your account is ready\. You can now sign in as (.+)$/u, (match) => `आपका खाता तैयार है। अब आप ${match[1]} के रूप में साइन इन कर सकते हैं`],
  [/^Link valid until (.+)$/u, (match) => `लिंक की वैधता ${match[1]} तक है`],
  [/^Submitted (\d.*)$/u, (match) => `${match[1]} को जमा किया गया`],
  [/^(\d+)% complete$/u, (match) => `${match[1]}% पूरा`],
  [/^Development code: (.+)$/u, (match) => `विकास कोड: ${match[1]}`],
  [/^(\d+(?:\.\d+)?)% p\.a\.$/iu, (match) => `${match[1]}% वार्षिक`],
  [/^Step (\d+) of (\d+)$/u, (match) => `${match[2]} में से चरण ${match[1]}`],
  [/^Step (\d+) of (\d+) · (.+)$/u, (match) => `${match[2]} में से चरण ${match[1]} · ${translateText(match[3], 'hi')}`],
  [/^(.+): (.+) – (.+) · indicative rate (.+) p\.a\.$/u, (match) => `${translateText(match[1], 'hi')}: ${match[2]} – ${match[3]} · सांकेतिक दर ${match[4]} वार्षिक`],
  [/^(.+) – (.+) months available\.$/u, (match) => `${match[1]} – ${match[2]} महीने उपलब्ध।`],
  [/^₹([\d,]+)\s*(K|L)?\s*[–-]\s*₹([\d,]+)\s*(K|L)?$/iu, (match) => {
    const unit = (value) => value?.toUpperCase() === 'K' ? ' हज़ार' : value?.toUpperCase() === 'L' ? ' लाख' : '';
    return `₹${match[1]}${unit(match[2])} – ₹${match[3]}${unit(match[4])}`;
  }],
];

export function translateText(value, locale = 'en') {
  if (locale !== 'hi') return value;
  const key = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (HINDI[key]) return HINDI[key];
  const caseInsensitive = HINDI_CASE_INSENSITIVE.get(key.toLocaleLowerCase());
  if (caseInsensitive) return caseInsensitive;
  for (const [pattern, render] of DYNAMIC_TRANSLATIONS) {
    const match = pattern.exec(key);
    if (match) return render(match);
  }
  return value;
}

/**
 * Translates the visible content of a text node while leaving its surrounding
 * whitespace exactly as it was.
 *
 * A text node that is *only* whitespace (the indentation between two elements)
 * is returned untouched. Rebuilding such a node from its leading and trailing
 * runs would duplicate the whitespace it is made of, because those two runs are
 * the entire string, so the node grows on every locale switch.
 */
export function translateTextPreservingWhitespace(value, locale = 'en') {
  const source = String(value ?? '');
  const content = source.trim();
  if (content === '') return source;
  return source.replace(content, () => translateText(content, locale));
}